const fs = require('node:fs');
const crypto = require('node:crypto');
const paths = ['products/services/open-software-tenders/refresh-20261114/source-105246-2026.json', 'products/services/tender-refresh/raw/105246-2026.json'];
const captures = paths.map(path => {
  const bytes = fs.readFileSync(path);
  const source = JSON.parse(bytes);
  return {path, sha256: crypto.createHash('sha256').update(bytes).digest('hex'), releases: (source.releases ?? []).map(({id, ocid, date, tag, tender}) => ({id, ocid, date, tag, title: tender?.title, status: tender?.status, tenderPeriod: tender?.tenderPeriod, submissionMethod: tender?.submissionMethod, submissionMethodDetails: tender?.submissionMethodDetails}))};
});
const live = fs.readFileSync('products/distribution/expiry-verification/open-software-tenders-2026-11-18.html', 'utf8');
const liveExcerpts = live.split('\n').filter(line => line.includes('105246-2026')).map(line => line.trim());
console.log(JSON.stringify({scope: 'Saved capture comparison. Dates and status here establish only what the saved releases stated. Check the current official release before recommending a correction.', captures, liveExcerpts}, null, 2));
